import React, { useState, useEffect } from "react";
import { collection, addDoc, getDocs, deleteDoc, doc, updateDoc } from "firebase/firestore";
import { db } from "../../firebaseConfig";
import { getAuth, signInWithEmailAndPassword, signOut } from "firebase/auth";
import "./ManageTeachers.css";

const AdminManageTeachers = () => {
  const [teachers, setTeachers] = useState([]);
  const [form, setForm] = useState({
    name: "",
    email: "",
    subject: "",
    password: "",
  });
  const [editId, setEditId] = useState(null);
  const [user, setUser] = useState(null);
  const [authError, setAuthError] = useState("");

  const teachersCollectionRef = collection(db, "teachers");
  const auth = getAuth();

  // Fetch teachers from Firestore
  const fetchTeachers = async () => {
    const data = await getDocs(teachersCollectionRef);
    setTeachers(data.docs.map((doc) => ({ ...doc.data(), id: doc.id })));
  };

  useEffect(() => {
    fetchTeachers();
  }, []);

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged(setUser);
    return () => unsubscribe();
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setForm({ ...form, [name]: value });
  };

  const addOrUpdateTeacher = async (e) => {
    e.preventDefault();
    if (editId) {
      const teacherDoc = doc(db, "teachers", editId);
      await updateDoc(teacherDoc, form);
    } else {
      await addDoc(teachersCollectionRef, form);
    }
    fetchTeachers();
    setForm({ name: "", email: "", subject: "", password: "" });
    setEditId(null);
  };

  const deleteTeacher = async (id) => {
    const teacherDoc = doc(db, "teachers", id);
    await deleteDoc(teacherDoc);
    fetchTeachers();
  };

  const editTeacher = (teacher) => {
    setForm(teacher);
    setEditId(teacher.id);
  };

  const logout = async () => {
    await signOut(auth);
  };

  return (
    <div className="manage-teachers-container">
      {user ? (
        <>
          <h2>Manage Teachers</h2>
          <button onClick={logout} className="logout-btn">Logout</button>

          <form onSubmit={addOrUpdateTeacher} className="teacher-form">
            <label htmlFor="name">Name:</label>
            <input
              type="text"
              id="name"
              name="name"
              value={form.name}
              onChange={handleInputChange}
              required
            />

            <label htmlFor="email">Email:</label>
            <input
              type="email"
              id="email"
              name="email"
              value={form.email}
              onChange={handleInputChange}
              required
            />

            <label htmlFor="subject">Subject:</label>
            <input
              type="text"
              id="subject"
              name="subject"
              value={form.subject}
              onChange={handleInputChange}
              required
            />

            <label htmlFor="password">Password:</label>
            <input
              type="password"
              id="password"
              name="password"
              value={form.password}
              onChange={handleInputChange}
              required
            />

            <button type="submit" className="form-btn">
              {editId ? "Update Teacher" : "Add Teacher"}
            </button>
          </form>

          <table className="teachers-table">
            <thead>
              <tr>
                <th>Name</th>
                <th>Email</th>
                <th>Subject</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {teachers.map((teacher) => (
                <tr key={teacher.id}>
                  <td>{teacher.name}</td>
                  <td>{teacher.email}</td>
                  <td>{teacher.subject}</td>
                  <td>
                    <button onClick={() => editTeacher(teacher)} className="edit-btn">
                      Edit
                    </button>
                    <button onClick={() => deleteTeacher(teacher.id)} className="delete-btn">
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </>
      ) : (
        <div className="login-container">
          <h2>Teacher Login</h2>
          {authError && <p className="error">{authError}</p>}
          <form
            onSubmit={(e) => {
              e.preventDefault();
              login(form.email, form.password);
            }}
            className="login-form"
          >
            <label htmlFor="email">Email:</label>
            <input
              type="email"
              id="email"
              name="email"
              value={form.email}
              onChange={handleInputChange}
              required
            />

            <label htmlFor="password">Password:</label>
            <input
              type="password"
              id="password"
              name="password"
              value={form.password}
              onChange={handleInputChange}
              required
            />

            <button type="submit" className="login-btn">Login</button>
          </form>
        </div>
      )};
    </div>
  );
};

export default AdminManageTeachers;
